-- Neue Tabelle für die in der Produktionsplanung erfassten Störungen/Stillstände.
-- Einmalig in der PostgreSQL-Datenbank (Render) ausführen. Mehrfaches Ausführen schadet nicht.

CREATE TABLE IF NOT EXISTS "PlanungStoerungen" (
    "Id"          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Datum"       TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "MaschinenId" BIGINT       NOT NULL,
    "Von"         INTERVAL     NOT NULL,
    "Bis"         INTERVAL     NOT NULL,
    "Grund"       VARCHAR(200) NULL
);

CREATE INDEX IF NOT EXISTS "IX_PlanungStoerungen_Datum_Maschine"
    ON "PlanungStoerungen" ("Datum", "MaschinenId");
